import { isPresetRef, type PresetRef } from "../presets/index.ts";

export const AGENTS_MD_MARKER =
  "<!-- AUTO-GENERATED by repotruck. Do not edit by hand; this file is rewritten on every sync or clone. -->";

export const CUSTOM_INSTRUCTIONS_BEGIN =
  "<!-- repotruck:custom-instructions begin (this section is preserved verbatim on every rewrite) -->";
export const CUSTOM_INSTRUCTIONS_END = "<!-- repotruck:custom-instructions end -->";
export const CUSTOM_INSTRUCTIONS_PLACEHOLDER =
  "(add your own instructions for coding agents — they survive repotruck rewrites)";

export const TEMPLATE_BLOCK_BEGIN =
  "<!-- repotruck:template begin (this section is regenerated from the selected template on every rewrite) -->";
export const TEMPLATE_BLOCK_END = "<!-- repotruck:template end -->";

export interface AgentsMdTemplateBlock {
  name: string;
  body: string;
}

export interface AgentsMdRepo {
  owner: string;
  name: string;
  relativePath: string;
  internal: boolean;
  category?: string | null;
  language?: string | null;
}

export interface AgentsMdWorktree {
  relativePath: string;
  mainRepoDir?: string | null;
}

export interface GenerateAgentsMdInput {
  preset: PresetRef;
  lastSync: string | null;
  repos: readonly AgentsMdRepo[];
  customInstructions?: string | null;
  aliases?: Record<string, string>;
  template?: AgentsMdTemplateBlock | null;
  pinned?: readonly string[];
  worktrees?: readonly AgentsMdWorktree[];
}

export function extractCustomInstructions(content: string): string | null {
  const beginIndex = content.indexOf(CUSTOM_INSTRUCTIONS_BEGIN);
  if (beginIndex === -1) return null;
  const newlineIndex = content.indexOf("\n", beginIndex);
  if (newlineIndex === -1) return "";
  const endIndex = content.indexOf(CUSTOM_INSTRUCTIONS_END, newlineIndex);
  if (endIndex === -1) {
    const rest = content.slice(newlineIndex + 1);
    return rest.endsWith("\n") ? rest.slice(0, -1) : rest;
  }
  const inner = content.slice(newlineIndex + 1, endIndex);
  return inner.endsWith("\n") ? inner.slice(0, -1) : inner;
}

export function extractTemplateBlock(content: string): AgentsMdTemplateBlock | null {
  const beginIndex = content.indexOf(TEMPLATE_BLOCK_BEGIN);
  // Only trust the template name line that precedes the template block, so a
  // look-alike line inside custom instructions cannot hijack the name.
  const nameMatch = /^- Instructions template: `?([A-Za-z0-9-]+)`?\s*$/m.exec(
    beginIndex === -1 ? content : content.slice(0, beginIndex),
  );
  if (nameMatch === null || beginIndex === -1) return null;
  const name = nameMatch[1]!;
  const newlineIndex = content.indexOf("\n", beginIndex);
  if (newlineIndex === -1) return { name, body: "" };
  const endIndex = content.indexOf(TEMPLATE_BLOCK_END, newlineIndex);
  if (endIndex === -1) {
    const rest = content.slice(newlineIndex + 1);
    const body = rest.endsWith("\n") ? rest.slice(0, -1) : rest;
    return { name, body };
  }
  const inner = content.slice(newlineIndex + 1, endIndex);
  const body = inner.endsWith("\n") ? inner.slice(0, -1) : inner;
  return { name, body };
}

function templateBlockLines(template: AgentsMdTemplateBlock): string[] {
  return [TEMPLATE_BLOCK_BEGIN, template.body, TEMPLATE_BLOCK_END];
}

function customInstructionsBlock(
  customInstructions?: string | null,
  template?: AgentsMdTemplateBlock | null,
): string[] {
  const body =
    customInstructions !== undefined && customInstructions !== null && customInstructions.length > 0
      ? customInstructions
      : CUSTOM_INSTRUCTIONS_PLACEHOLDER;
  const lines: string[] = ["", "## Custom Instructions", ""];
  if (template !== undefined && template !== null) {
    lines.push(...templateBlockLines(template), "");
  }
  lines.push(CUSTOM_INSTRUCTIONS_BEGIN, body, CUSTOM_INSTRUCTIONS_END);
  return lines;
}

function sortRepos(repos: readonly AgentsMdRepo[]): AgentsMdRepo[] {
  return [...repos].sort((a, b) =>
    a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0,
  );
}

function aliasesByPath(aliases?: Record<string, string>): Map<string, string[]> {
  const map = new Map<string, string[]>();
  if (aliases === undefined) return map;
  for (const [alias, target] of Object.entries(aliases)) {
    const key = target.toLowerCase();
    const list = map.get(key) ?? [];
    list.push(alias);
    map.set(key, list);
  }
  return map;
}

function renderEntry(repo: AgentsMdRepo, aliasByPath?: Map<string, string[]>): string {
  const badges: string[] = [];
  if (repo.category === "archived") badges.push("archived");
  if (repo.category === "forks") badges.push("fork");
  if (typeof repo.language === "string" && repo.language.length > 0) {
    badges.push(repo.language);
  }
  const suffix = badges.length > 0 ? ` (${badges.join(", ")})` : "";
  const repoAliases =
    aliasByPath === undefined
      ? []
      : (aliasByPath.get(repo.relativePath.toLowerCase()) ?? []).sort((a, b) => a.localeCompare(b));
  const aliasSuffix = repoAliases.length > 0 ? ` (alias: ${repoAliases.join(", ")})` : "";
  return `- \`${repo.owner}/${repo.name}\` — \`${repo.relativePath}\`${suffix}${aliasSuffix}`;
}

export function generateAgentsMd(input: GenerateAgentsMdInput): string {
  const aliasByPath = aliasesByPath(input.aliases);
  const internal = sortRepos(input.repos.filter((repo) => repo.internal));
  const community = sortRepos(input.repos.filter((repo) => !repo.internal));
  const internalCount = internal.length;
  const communityCount = community.length;
  const lastSync = input.lastSync ?? "never";

  const pinnedSet = new Set((input.pinned ?? []).map((item) => item.toLowerCase()));
  const pinnedRepos =
    pinnedSet.size > 0
      ? sortRepos(
          input.repos.filter((repo) => pinnedSet.has(`${repo.owner}/${repo.name}`.toLowerCase())),
        )
      : [];

  const lines: string[] = [
    AGENTS_MD_MARKER,
    "",
    "# Repository Workspace Map",
    "",
    "## Workspace Metadata",
    "",
    `- Preset: \`${input.preset}\``,
  ];

  if (input.template !== undefined && input.template !== null) {
    lines.push(`- Instructions template: \`${input.template.name}\``);
  }

  lines.push(
    `- Last sync: ${lastSync}`,
    `- Total repositories: ${internalCount + communityCount} (${internalCount} internal, ${communityCount} community)`,
  );

  if (pinnedRepos.length > 0) {
    lines.push("", "## Active Focus (Pinned)", "");
    for (const repo of pinnedRepos) {
      lines.push(renderEntry(repo, aliasByPath));
    }
  }

  lines.push("", "## Internal Projects", "");

  if (internal.length === 0) {
    lines.push("*(none yet)*");
  } else {
    for (const repo of internal) lines.push(renderEntry(repo, aliasByPath));
  }

  lines.push("", "## Community Repositories (community/)", "");

  if (community.length === 0) {
    lines.push("*(none yet)*");
  } else {
    for (const repo of community) lines.push(renderEntry(repo, aliasByPath));
  }

  if (input.worktrees !== undefined && input.worktrees.length > 0) {
    lines.push("", "## Linked Git Worktrees", "");
    for (const wt of input.worktrees) {
      const parentNote =
        wt.mainRepoDir !== undefined && wt.mainRepoDir !== null
          ? ` (linked from \`${wt.mainRepoDir}\`)`
          : "";
      lines.push(`- \`${wt.relativePath}\`${parentNote} — linked worktree; keep in place`);
    }
  }

  lines.push(
    "",
    "## Agent Rules",
    "",
    "- Each directory is an independent Git project; run Git commands inside the project directory, never from the workspace root.",
    "- Exclude `.git/`, `node_modules/`, and `dist/` directories from global searches.",
    "- Repositories under `community/` are read-only references; never suggest commit or push for them without an explicit user request.",
    "- When a repotruck MCP server is connected, prefer its tools (repotruck_list_repos, repotruck_resolve_repo, repotruck_sync, ...) for workspace navigation and updates; otherwise use the `repotruck` CLI.",
  );

  for (const line of customInstructionsBlock(input.customInstructions, input.template)) {
    lines.push(line);
  }

  lines.push("");

  return lines.join("\n");
}

export function parsePresetFromAgentsMd(content: string): PresetRef | null {
  const match = /^- Preset: `?([A-Za-z0-9-]+)`?\s*$/m.exec(content);
  if (match === null) return null;
  const candidate = match[1];
  return isPresetRef(candidate) ? candidate : null;
}
